using Studio;using UnityEngine;using A=AlignedPlacement.AlignedPlacement;
int checks=0,failures=0;void Check(bool b,string why){if(!b)throw new Exception(why);}void Test(string n,Action a){checks++;try{a();Console.WriteLine("PASS "+n);}catch(Exception e){failures++;Console.WriteLine("FAIL "+n+" "+e.GetBaseException().GetType().Name+":"+e.GetBaseException().Message);}}
GuideObject[] Make(bool mixed=false,bool disabled=false){var guides=Enumerable.Range(1,3).Select(i=>new GuideObject{dicKey=i,enablePos=!disabled&&(!mixed||i!=2),transformTarget=new Transform{position=new(i*10,0,0)}}).ToArray();foreach(var g in guides){g.changeAmount.pos=g.transformTarget.position;GuideCommand.Amounts[g.dicKey]=g.changeAmount;}Singleton<GuideObjectManager>.Instance=new(){selectObjects=guides};Singleton<UndoRedoManager>.Instance=new();return guides;}
IEnumerable<GuideCommand.EqualsInfo> Infos(ICommand c)=>c is GuideCommand.MoveEqualsCommand m?m.changeAmountInfo:((GuideCommand.RotationEqualsCommand)c).changeAmountInfo;
foreach(string method in new[]{"ApplyLinearMove","ApplyLinearRotation","ApplyCircularPlacement"}){
Test(method+" normal command and undo",()=>{var guides=Make();var p=new A();typeof(A).GetMethod(method).Invoke(p,null);var commands=Singleton<UndoRedoManager>.Instance.Commands;Check(commands.Count==(method=="ApplyCircularPlacement"?2:1),"command count changed");Check(commands.All(c=>Infos(c).Count()==3),"normal membership changed");foreach(var c in commands.AsEnumerable().Reverse())c.Undo();Check(guides.All(g=>g.changeAmount.pos.x==g.dicKey*10&&g.changeAmount.rot.y==0),"undo did not restore");});
Test(method+" mixed disabled guide does not crash or enter undo",()=>{var guides=Make(true);var p=new A();typeof(A).GetMethod(method).Invoke(p,null);var commands=Singleton<UndoRedoManager>.Instance.Commands;Check(commands.Count==(method=="ApplyCircularPlacement"?2:1),"missing command");Check(commands.All(c=>Infos(c).All(x=>x.dicKey!=2)),"disabled guide in history");Check(guides[1].changeAmount.pos.x==20&&guides[1].changeAmount.rot.y==0,"disabled changed");foreach(var c in commands.AsEnumerable().Reverse())c.Undo();Check(guides.All(g=>g.changeAmount.pos.x==g.dicKey*10),"movable undo failed");});
Test(method+" all disabled does not add empty history",()=>{Make(false,true);var p=new A();typeof(A).GetMethod(method).Invoke(p,null);Check(Singleton<UndoRedoManager>.Instance.Commands.Count==0,"empty history added");});}
Test("one selection remains noop",()=>{var g=Make()[0];Singleton<GuideObjectManager>.Instance.selectObjects=new[]{g};var p=new A();p.ApplyLinearMove();p.ApplyLinearRotation();p.ApplyCircularPlacement();Check(Singleton<UndoRedoManager>.Instance.Commands.Count==0,"single selection mutated history");});
Console.WriteLine($"checks={checks} failures={failures}");return failures==0?0:1;
